package main

import (
	"bufio"
	"fmt"
	"os"
)

var (
	s   string
	n   int64
	l   int64
)

func check(a int64) bool {
	for i := int64(1); i <= a-n; i++ {
		if s[int(l-i)] != s[int(l-i-a)] {
			return false
		}
	}
	return true
}

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	fmt.Fscan(in, &s)
	l = int64(len(s))
	fmt.Fscan(in, &n)

	var min int64
	if n > l {
		min = (l + n) / 2
	} else {
		min = n
	}

	max := (l + n) / 2
	var ans, temp int64

	for i := int64(0); i < l; i++ {
		for j := int64(1); j*2+i <= l; j++ {
			key := true
			for k := int64(1); k <= j; k++ {
				if s[int(i+k-1)] != s[int(i+k+j-1)] {
					key = false
				}
			}
			if key && j > temp {
				temp = j
			}
		}
	}

	for i := max; i >= min && ans == 0; i-- {
		if check(i) {
			ans = i
		}
	}

	if min > ans {
		ans = min
	}
	if temp > ans {
		ans = temp
	}

	fmt.Fprint(out, 2*ans)
}

